mapper.update:
UPDATE user_bgm_collection SET subject_type=#{row.subjectType}, type=#{row.type}, rate=#{row.rate}, comment=#{row.comment},
    tags=#{row.tags}, is_private=#{row.isPrivate}, local_updated_at=#{row.localUpdatedAt},
    version=#{row.version}, pending_payload=#{row.pendingPayload}, remote_baseline=NULL,
    remote_sync_status=#{row.remoteSyncStatus}, sync_oauth_id=#{row.syncOauthId},
    bgm_account_uid=#{row.bgmAccountUid}, retry_count=0, next_retry_at=#{row.nextRetryAt}
WHERE id=#{row.id}

UPDATE user_bgm_collection SET bgm_interest_id=#{row.bgmInterestId},
    bgm_updated_at=#{row.bgmUpdatedAt}, sync_time=#{row.syncTime},
    pending_payload=#{row.pendingPayload}, remote_baseline=#{row.remoteBaseline},
    remote_sync_status=#{row.remoteSyncStatus}, retry_count=#{row.retryCount},
    next_retry_at=#{row.nextRetryAt}
WHERE id=#{row.id} AND version=#{row.version}

mapper.sql:
WHERE c.user_id = #{userId}
  AND c.type = #{type}
  AND c.subject_type = #{subjectType}

  AND (
      s.name LIKE CONCAT('%', #{keyword}, '%')
      OR s.name_cn LIKE CONCAT('%', #{keyword}, '%')
  )
